import json
from pathlib import Path
from shapely.geometry import shape,mapping,box
from shapely.ops import unary_union
P=Path(__file__).parent
ways=json.load(open(P/'source-ways.geojson'))['features']
base=json.load(open(P/'street-traces.json'))['units'];base=[f for f in base if f['name'] not in ['Manninger János lakótelep','Móra Ferenc-lakótelep']]
specs=[dict(name='Manninger János lakótelep',roads=['Manninger János lakótelep'],sourceUrl='https://njt.jog.gov.hu/jogszabaly/2017-42-SP-5Y3437.3',supportingUrls=['https://www.openstreetmap.org/node/3187630933'],note='The municipal townscape ordinance separately names Manninger lakótelep as a housing estate. The estimate uses the envelope of the four source road ways explicitly carrying the full estate name. It is a coarse interior estate extent, not the larger surrounding block also containing the Móra locality.'),dict(name='Móra Ferenc-lakótelep',roads=['Móra Ferenc lakótelep'],sourceUrl='https://njt.jog.gov.hu/jogszabaly/2019-33-SP-5Y3437.0',supportingUrls=['https://www.openstreetmap.org/node/11587440434'],note='Municipal street/constituency documentation names Móra Ferenc lakótelep separately. The three internal estate-named road ways define this coarse envelope. The source neighbourhood label lies north-west of these named estate roads; it is not used to stretch the geometry into the separately named Manninger estate. Buildings outside the internal road envelope may be omitted.'),dict(name='Duna lakópark',roads=['Erzsébet királyné út','Konrád utca','Géza fejedelem utca','Bocskai István utca','Bethlen Gábor utca','Zsigmond király utca','Nagy Lajos király út','Zita királyné utca','Gizella királyné út','Zsófia királyné utca','Wathay Ferenc út','Károly Róbert út','Sőtér Ágost tér','Bornemissza Péter utca','Albert Kázmér utca','Akadémia tér'],sourceUrl='https://www.mve1985.hu/images/CLLD/I_resz.pdf',supportingUrls=['https://mosonvarmegye.net/hirek/hetvezer-ut-es-cirbolya-koz','https://www.openstreetmap.org/node/3354084134'],note='The 2021 city history identifies Duna lakópark as a separate northern extension of Majorok; the local municipal-news report explains that its streets take the names of Hungarian monarchs and historical figures. The envelope of this explicit, locally connected estate street set estimates the built estate rather than copying the entire Majorok quarter. Parcel edges and later phases are not resolved.'),dict(name='Lajta lakókert',roads=['Háncs utca','Pázsit utca','Dohy János utca','Zsilip utca','Lomb utca','Inda utca','Kalász utca','Pacsirta utca','Sárvíz utca','Bokréta utca','Bryozoa utca','Venus utca'],sourceUrl='https://www.mve1985.hu/images/CLLD/I_resz.pdf',supportingUrls=['https://njt.jog.gov.hu/jogszabaly/2014-20-SP-5Y3437.3','https://www.mosonmagyarovar.hu/websites/www.mosonmagyarovar.hu/files/dokumentumok/telepulesrendezes/Telepulesfejlesztesi-eszkozok/2_FVS_Strategiai_munkaresz.pdf','https://www.openstreetmap.org/node/2692495938'],note='The city history describes Lajta lakókert as the new housing quarter across the Lajta bridge from Mofém; the FVS identifies its Lomb utcai park. The envelope follows the connected small residential street set visible on the source map and archived OSM street plan. The Dohy and Háncs limits may include neighbouring plots; riverbank and parcel-side boundaries remain approximate.')]
for s in specs:
 fs=[f for f in ways if f['properties']['name'] in s['roads']]
 if s['name']=='Lajta lakókert':
  scope=box(17.254,47.8805,17.2684,47.889)
  fs=[f for f in fs if scope.covers(shape(f['geometry']))]
 if not fs:raise ValueError(s['name'])
 poly=unary_union([shape(f['geometry']) for f in fs]).convex_hull
 if not poly.is_valid or poly.geom_type!='Polygon':raise ValueError(s['name'])
 base.append(dict(name=s['name'],id='estimated:mosonmagyarovar:road-estate:'+s['name'],method='Explicitly estimated envelope of the archived named estate street network: convex hull of the source vertices of the documented/identified local estate streets; no neighbourhood-point buffer or Voronoi construction.',sourceUrl=s['sourceUrl'],supportingUrls=s['supportingUrls'],sourceLineIds=[f['id'].replace('osm:','').replace(':','/') for f in fs],sourcePeriod='2021 city-history context and OSM snapshot 2026-11-12',approximationNote=s['note']+' Straight segments between the outer source street vertices are an estimate, not surveyed estate boundaries.',roadsConsidered=s['roads'],geometry=mapping(poly)))
(P/'street-traces.json').write_text(json.dumps(dict(units=base),ensure_ascii=False,indent=2)+'\n')
print('Total distinct street/road-estate estimates:',len(base))
